<br />\mathdisp {X= \bigcup_{i \in I} U_i \, \, \, \text{ mit } U_i \text{ offen und einer beliebigen Indexmenge }I} {  }<br />
eine endliche Teilmenge
<br />\mavergleichskette<br />{\vergleichskette<br />{J
}<br />{ \subseteq }{ I
}<br />{  }{
}<br />{    }{
}<br />{   }{
}<br />}
{}{}{}
